window.docContents[117].resolve({"/Equiv/#Hoare-Logic--Equiv___-Program-Equivalence--Program-Transformation--Soundness-of-Constant-Folding":{"contents":"\n\n\n\ntheorem Aexp.foldConstants_sound : TransSound foldConstants := by\n  rw [transSound_def]\n  intro a\n  rw [equiv_def]\n  intro st\n  induction a with\n  | num n | id x => rfl\n  | _ a₁ a₂ _ _ =>\n    cases foldConstants_cases a₁ a₂ with\n    | inl h =>\n      obtain ⟨n₁, n₂, h₁, h₂⟩ := h\n      rw [foldConstants]\n      simp_all\n    | inr h =>\n      simp_all\n\n-- Golfed version with `fun_induction`\ntheorem Aexp.foldConstants_sound' : TransSound foldConstants := by\n  rw [transSound_def]\n  intro a\n  rw [equiv_def]\n  intro st\n  fun_induction foldConstants a <;> simp_all\n\n\nNOT PORTED YET - remaining portions of Equiv.v left (apart from the portions explicitly stated so far).\n  - The section on \"Program Transformation\"\n  - Soundness of (0 + n) Elimination\n  - Extended Exercise: Nondeterministic Imp\n  - Additional Exercises\n\n\n","context":"Hoare Logic\u0009Equiv: Program Equivalence\u0009Program Transformation","header":"4.3.2. Soundness of Constant Folding","id":"/Equiv/#Hoare-Logic--Equiv___-Program-Equivalence--Program-Transformation--Soundness-of-Constant-Folding"}});